// Тикет #bad2d0dd (bad2d0dd5689a4c0bdaa74b6) — עבר QA 14.10.2026 (реальный iPhone, TestFlight 1.0.0 (20)).
// Факты 14.10 (скрины bad2d0dd-ios-b20-*): номер, не завершивший регистрацию, после OTP попадает на «יצירת חשבון» —
// там есть кнопка «חזרה» (accessibility name 'חזרה', круглая справа сверху); после холодного перезапуска снова «יצירת חשבון» с «חזרה»;
// «חזרה» → «כניסה דרך מספר נייד» (что в поле номера — не проверяем: пусто/мокап-номер — норма).
// Аккаунт, нажавший «שלח», но не прошедший настройку, после перезапуска открывается на «תאריך לידה» с «חזרה» → тоже экран входа.
// После выхода можно войти другим номером (USER1).
// «התנתקות» в «פרופיל אישי» без настройки — недостижимо, не проверялось 14.10 → в тест не входит.
// РЕГИСТРАЦИЮ И КОДЫ ДЕЛАЕТ ЧЕЛОВЕК (@manual-check). Запуск: QA_REG_MANUAL=1, иначе skip.
// РУЧНЫЕ ШАГИ (человек, тест ждёт до 15 минут на каждом):
//  RG-06a: «בואו נתחיל» → в поле НОВЫЙ номер (без аккаунта) → «שילחו קוד אימות» → код. На «יצירת חשבון» НИЧЕГО не заполнять.
//  RG-06b: снова войти ТЕМ ЖЕ номером → «יצירת חשבון»: «שם מלא *» (QA-AUTO-…), «אימייל *», галочка условий → «שלח» → «יש! יצרת חשבון» → «בואו נתקדם» (порядок с 19.10, #f688d2b0) → дойти до «תאריך לידה» и остановиться.
// Тест сам: холодный перезапуск (terminateApp/activateApp), проверки, нажатия ТОЛЬКО по accessibility name — без тапов по координатам
// (верхние 140 pt перехватывают баннеры уведомлений).
// @data: в RG-06b создаётся аккаунт без настройки (удалить из приложения нельзя — записать в test_data). Номер можно доиспользовать в RG-07.
// В конце — вход USER1.
import { driver, expect } from '@wdio/globals';
import { byText, byLabel } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout, login } from '../../helpers/app.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { appId } from '../_lib/app-1310b.ts';

const CREATE = 'יצירת חשבון';
const BIRTHDATE = 'תאריך לידה';
const LOGIN_TITLE = 'כניסה דרך מספר נייד';
const MANUAL_WAIT = 900000;

async function coldRestart() {
  const id = appId();
  if (!id) throw new Error('нет APP_IOS_BUNDLE / APP_ANDROID_PACKAGE — холодный перезапуск невозможен');
  await driver.terminateApp(id);
  await driver.activateApp(id);
}

async function waitManual(title: string, what: string) {
  console.log(`[RG-06] @manual-check: ${what}. Тест ждёт «${title}» до 15 минут…`);
  await (await byText(title)).waitForDisplayed({ timeout: MANUAL_WAIT, interval: 3000, timeoutMsg: `не дождались «${title}»` });
}

/** Экран с заголовком title: есть «חזרה» (по label); нажатие → «כניסה דרך מספר נייד», title ушёл. */
async function expectBackToLogin(title: string) {
  await expect(byText(title)).toBeDisplayed({ wait: 30000 });
  const back = await byLabel('חזרה');
  await expect(back).toBeDisplayed({ wait: 10000 });
  await back.click();
  await expect(byText(LOGIN_TITLE)).toBeDisplayed({ wait: 20000 });
  await expect(byText(title)).not.toBeDisplayed();
  await expect(byText('בית')).not.toBeDisplayed();
}

async function ensureLoggedOut() {
  if (await isLoggedIn()) await logout();
}

describe('Регистрация: выход из незавершённой регистрации', () => {
  beforeEach(function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'вход новым номером с OTP — вручную; запуск с QA_REG_MANUAL=1 и человеком у телефона');
  });

  it('RG-06a Номер без завершённой регистрации: «יצירת חשבון» с «חזרה», после холодного перезапуска снова «יצירת חשבון» с «חזרה» → «כניסה דרך מספר נייד» #bad2d0dd @manual-check', async function () {
    this.timeout(1200000);
    await ensureLoggedOutSafe();
    await waitManual(CREATE, 'войдите НОВЫМ номером (без аккаунта) и введите код; форму «יצירת חשבון» не заполнять');
    await expect(byLabel('חזרה')).toBeDisplayed({ wait: 10000 });

    await coldRestart();
    await expectBackToLogin(CREATE);
  });

  it('RG-06b Аккаунт после «שלח» без настройки: после холодного перезапуска «תאריך לידה» с «חזרה» → «כניסה דרך מספר נייד»; затем вход другим номером (USER1) #bad2d0dd @data @manual-check', async function () {
    this.timeout(1200000);
    try {
      await ensureLoggedOutSafe();
      await waitManual(BIRTHDATE, 'войдите тем же номером, заполните «יצירת חשבון» (QA-AUTO-…), галочка условий, «שלח» → «בואו נתקדם»; остановитесь на «תאריך לידה»');
      await coldRestart();
      await expectBackToLogin(BIRTHDATE);

      // После выхода можно войти другим номером.
      await login('USER1');
      await driver.waitUntil(isLoggedIn, { timeout: 30000, timeoutMsg: 'вход другим номером (USER1) не открыл главную' });
    } finally {
      if (!(await isLoggedIn())) {
        try { await login('USER1'); } catch (e) { console.warn('[RG-06] вернуть вход USER1 вручную', e); await ensureAppReady().catch(() => {}); }
      }
    }
  });
});

/** Выйти, если вошли; если открыт экран незавершённой регистрации — выйти через «חזרה». */
async function ensureLoggedOutSafe() {
  if (await shown(byText(CREATE)) || await shown(byText(BIRTHDATE))) {
    const back = await byLabel('חזרה');
    if (await back.isDisplayed().catch(() => false)) await back.click();
    return;
  }
  await ensureLoggedOut();
}
